/* V4 presentation layer. Existing API contracts and business operations remain in app.js. */
const V4_ICONS={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5"/>',research:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6M7 10h6m-3-3v6"/>',assets:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1"/><path d="m3 17 6-6 5 5 3-3 4 4"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="m3 6 9 7 9-7"/>',pipeline:'<path d="M4 20V12m5 8V5m6 15v-9m5 9V2"/>',settings:'<path d="m9 3-1 3-3 1v4l2 1-1 3 3 3 3-1 2 2 3-2v-3l3-2-1-4-3-1-2-3Z"/><circle cx="12" cy="11" r="3"/>',ai:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',reply:'<path d="m9 5-6 6 6 6M3 11h10a8 8 0 0 1 8 8"/>',review:'<path d="M9 3h6l2 3h3v15H4V6h3Z"/><path d="m8 13 3 3 5-6"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',external:'<path d="M14 3h7v7m0-7L10 14M9 4H4v16h16v-5"/>',check:'<path d="m5 12 4 4L20 5"/>',note:'<path d="M4 3h16v14l-4 4H4ZM8 8h8m-8 4h8m-8 4h4"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>',more:'<circle cx="4" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="20" cy="12" r="1"/>',plus:'<path d="M12 4v16M4 12h16"/>'};
function icon(n,cls=''){return `<svg class="ui-icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${V4_ICONS[n]||V4_ICONS.ai}</svg>`}
const V4_VISUALS={"Dave's Rare Aquarium Fish":'daves', 'Aqua Huna':'aqua', 'Imperial Tropicals':'imperial', 'The Wet Spot Tropical Fish':'wetspot'};
function accountVisual(p){return V4_VISUALS[p?.company]?`./media/${V4_VISUALS[p.company]}.webp`:''}
function accountProducts(p){return V4_VISUALS[p?.company]?`./media/${V4_VISUALS[p.company]}-products.webp`:''}
function identityArt(p,large=false){const visual=accountVisual(p),f=p?favicon(p):'',key=V4_VISUALS[p?.company],pos={daves:'0%',aqua:'33.333%',imperial:'66.666%',wetspot:'100%'}[key];return `<div class="account-art ${large?'large':''} ${key?'scene-art':''}" ${key?`style="background-image:url('./media/aquatic-scenes.webp');background-position:${pos} center" role="img" aria-label="${esc(p.company)} aquarium illustration"`:''}>${!key&&f?`<img class="logo" src="${esc(f)}" alt="" loading="lazy" onerror="this.hidden=true">`:''}<span>${esc((p?.company||'M').split(/\s+/).slice(0,2).map(x=>x[0]).join(''))}</span></div>`}
function humanPhase(phase){return String(phase||'research').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase())}
function phaseTone(phase){return /reply|follow|waiting|review|approval|reminder/.test(phase)?'amber':/research|build/.test(phase)?'cyan':'lime'}
function phaseIcon(phase){return /reply/.test(phase)?'reply':/follow|waiting|reminder/.test(phase)?'clock':/review|approval/.test(phase)?'review':/research/.test(phase)?'research':/asset/.test(phase)?'assets':'mail'}
function timeAgo(d){if(!d)return '';const n=Math.max(0,Date.now()-new Date(d).getTime());return n<60000?'Just now':n<3600000?Math.floor(n/60000)+'m ago':n<86400000?Math.floor(n/3600000)+'h ago':Math.floor(n/86400000)+'d ago'}
function emptyState(title,copy,action=''){return `<div class="empty">${icon('ai')}<b>${esc(title)}</b><span>${esc(copy)}</span>${action}</div>`}
function sphere(){
 let nodes='',connections='';const count=Math.max(16,Math.min(76,todayQueue.length+data.prospects.length/5));const points=[];
 for(let i=0;i<count;i++){const y=1-2*i/(count-1),r=Math.sqrt(1-y*y),a=i*2.399963;const x=160+104*r*Math.cos(a),py=160+104*y,z=r*Math.sin(a);points.push([x,py,z]);nodes+=`<circle cx="${x.toFixed(1)}" cy="${py.toFixed(1)}" r="${z>0?2.1:1.1}" opacity="${z>0?.85:.25}"/>`;if(i>1&&i%2===0){const t=points[i-2];connections+=`<path d="M${x.toFixed(1)} ${py.toFixed(1)}L${t[0].toFixed(1)} ${t[1].toFixed(1)}" opacity=".14"/>`}}
 return `<svg class="signal-sphere" viewBox="0 0 320 320" role="img" aria-label="Intelligence network: ${todayQueue.length} ranked actions across ${data.prospects.length} accounts"><defs><radialGradient id="sphereLight"><stop offset="0" stop-color="#c4ff38" stop-opacity=".04"/><stop offset=".75" stop-color="#92c827" stop-opacity=".07"/><stop offset=".96" stop-color="#c4ff38" stop-opacity=".24"/><stop offset="1" stop-color="#58dde0" stop-opacity=".4"/></radialGradient><linearGradient id="orbitInk"><stop stop-color="#c4ff38"/><stop offset="1" stop-color="#58dde0"/></linearGradient></defs><g fill="none" stroke="#647177"><circle cx="160" cy="160" r="142" opacity=".18" stroke-dasharray="1 6"/><circle cx="160" cy="160" r="133" opacity=".16"/><path d="M48 78a138 138 0 0 1 145-53M273 239a138 138 0 0 1-84 56" stroke="#c4ff38" opacity=".65"/></g><image href="./media/intelligence-globe.webp" x="49" y="49" width="222" height="222"/><g class="sphere-net" fill="#c4ff38" stroke="#b7ed45" stroke-width=".5" opacity=".15">${nodes}</g><g fill="none" stroke="url(#orbitInk)"><ellipse class="sphere-orbit one" cx="160" cy="160" rx="119" ry="32" transform="rotate(-24 160 160)" opacity=".55"/><ellipse class="sphere-orbit two" cx="160" cy="160" rx="36" ry="112" transform="rotate(32 160 160)" opacity=".24"/><ellipse cx="160" cy="160" rx="89" ry="105" opacity=".15"/></g><circle class="signal-pulse" cx="246" cy="96" r="4" fill="#c4ff38"/><circle cx="69" cy="204" r="3" fill="#58dde0"/><circle cx="190" cy="55" r="3" fill="#c4ff38"/></svg>`;
}
renderCommand=function(){
 const reviews=data.asset_work_requests.filter(x=>x.status==='ready_for_review').length,replies=data.inbox_threads.filter(x=>x.status==='open'&&x.last_direction==='inbound').length,follow=data.workflow_state.filter(x=>x.phase==='follow_up'||/follow up/i.test(x.recommended_action)).length;
 $('#systemState').textContent=providerStatus.ai?'Morpheus intelligence active':'Workspace intelligence';$('#heroSummary').textContent='Your sales intelligence, in one place.';
 $('#commandSignals').innerHTML=[[data.prospects.length,'Prospects','people',''],[data.assets.length,'Assets','note',''],[priorityProspects().length,'Priority','ai','amber']].map(x=>`<button class="signal ${x[3]}" onclick="route('#/${x[2]==='note'?'assets':x[2]==='people'?'prospects':'pipeline'}')">${icon(x[2])}<strong>${x[0]}</strong><span>${x[1]}</span></button>`).join('');
 $('#todayPriorities').innerHTML=todayQueue.slice(0,3).map((x,i)=>{const p=data.prospects.find(p=>p.id===x.prospect_id),tone=phaseTone(x.action_kind);return `<article class="move-card ${tone}">${identityArt(p)}<div class="move-content"><div class="move-kicker">${icon(phaseIcon(x.action_kind))}<span>${esc(x.action_label||humanPhase(x.action_kind))}</span><span class="urgency">${x.score>=90?'Urgent':x.score>=70?'Priority':'Next'}</span></div><h3>${esc(x.title||p?.company||'Sales task')}</h3><p>${esc(x.reason||'Move this account forward.')}</p><div class="move-meta"><span class="micro-avatar">${esc((x.assigned_to||'T')[0])}</span>${esc(x.assigned_to||'Team')}<span class="move-category">${esc(x.category||'Sales OS')}</span></div></div><button class="btn move-action" onclick="runTodayItem(${i})">${esc(x.action_label||'Open')}${icon('arrow')}</button></article>`}).join('')||emptyState('A clear runway','Add a prospect or ask Morpheus to find your next opportunity.',`<button class="btn lime" onclick="openFindProspects()">Find prospects</button>`);
 $('#intelligenceVisual').innerHTML=sphere();$('#intelligenceReadout').innerHTML=`<div class="readout-total"><b>What shall we move forward today?</b></div><div class="readout-state"><span class="live-dot"></span>${todayQueue.length} ranked signals from CRM evidence</div>`;
 $('#commandAskAI').innerHTML=`${icon('ai')}<div><b>${priorityProspects().length} priority accounts</b><span>Ready for next step</span></div>`;$('#priorityCount')&&($('#priorityCount').textContent=todayQueue.length+' active moves');
 const a=[...data.activities].sort((x,y)=>new Date(y.occurred_at)-new Date(x.occurred_at)).slice(0,4);$('#teamActivity').innerHTML=a.map(x=>{const p=data.prospects.find(p=>p.id===x.prospect_id);return `<button class="activity-row" ${p?`onclick="route('#/prospect/${p.id}')"`:''}><span class="activity-icon ${x.activity_type==='Reply'?'amber':'cyan'}">${icon(x.activity_type==='Sent'?'mail':x.activity_type==='Reply'?'reply':'note')}</span><div><b>${esc(x.actor_name||x.activity_type||'Team')}</b><span>${esc(x.subject||x.outcome||p?.company||'Account updated')}</span><time>${esc(timeAgo(x.occurred_at))}</time></div>${p&&accountVisual(p)?`<img src="${accountVisual(p)}" alt="" loading="lazy">`:''}</button>`}).join('')||emptyState('No activity yet','Team actions will appear here.');
 const moving=data.workflow_state.filter(w=>/asset_ready|draft_ready|research_ready/.test(w.phase)).length,building=data.asset_work_requests.filter(j=>/queued|in_progress|changes_requested/.test(j.status)).length;
 $('#workflowHealth').innerHTML=`<div>${icon('pipeline')}<b>Workflow pulse</b><span>${moving} accounts ready to move</span></div><div class="health-track">${['research','asset_build','asset_review','draft_ready','waiting','reply'].map(phase=>`<button onclick="route('#/${phase==='asset_build'||phase==='asset_review'?'assets':phase==='research'?'research':'pipeline'}')"><i class="${phaseTone(phase)}" style="--fill:${Math.max(8,Math.min(100,data.workflow_state.filter(w=>w.phase===phase).length*8))}%"></i><span>${humanPhase(phase)}</span><b>${data.workflow_state.filter(w=>w.phase===phase).length}</b></button>`).join('')}</div><button class="text-link" onclick="route('#/assets')">${building} Ahamed jobs</button>`;
 $('#priorityProspects').innerHTML=priorityProspects().map(showcaseCard).join('');$('#commandCounts').textContent=`${data.prospects.length} accounts · ${data.assets.length} assets`;
 $('#syncLabel').textContent=data.synced_at?'Synced '+timeAgo(data.synced_at):'Live workspace';
};
showcaseCard=function(p){const w=workflowFor(p.id),phase=w?.phase||'research';return `<article class="showcase-card ${phaseTone(phase)}"><button class="card-open" onclick="route('#/prospect/${p.id}')"><div class="showcase-image">${identityArt(p,true)}<div class="account-brand">${icon(V4_VISUALS[p.company]==="aqua"||V4_VISUALS[p.company]==="wetspot"?"wavebrand":"fishbrand")}<b>${esc(p.company)}</b></div><span class="account-rank">${esc(p.priority||'Priority')}</span></div><div class="showcase-body"><div class="eyebrow">${esc(p.category||'Opportunity')}</div><h3>${esc(p.company)}</h3><p>${esc(p.segment||p.location||'Priority account')}</p><div class="showcase-footer"><span class="status-chip ${phaseTone(phase)}">${humanPhase(phase)}</span>${icon('arrow')}</div></div></button></article>`};
renderProspects=function(){syncFilters();const rows=filteredProspects();$('#prospectResults').textContent=rows.length+' accounts in view';$('#prospectGrid').innerHTML=rows.map(p=>{const w=workflowFor(p.id),job=pJobs(p.id)[0],phase=w?.phase||'research';return `<article class="prospect-card ${phaseTone(phase)}"><button class="card-open" onclick="route('#/prospect/${p.id}')"><div class="prospect-card-head">${identityArt(p)}<div><span class="eyebrow">${esc(p.category||'General')}</span><h3>${esc(p.company)}</h3><p>${esc(p.segment||p.location||'Opportunity account')}</p></div><span class="account-score">${p.score||'—'}<small>FIT</small></span></div><div class="card-mid"><span class="status-chip ${phaseTone(phase)}">${humanPhase(phase)}</span><span>${pAssets(p.id).length} assets${job?' · '+esc(job.status.replaceAll('_',' ')):''}</span></div><div class="prospect-card-footer"><div><small>NEXT MOVE</small><b>${esc(w?.recommended_action||p.next_action||'Define next action')}</b></div>${icon('arrow')}</div><div class="card-assignee"><span class="micro-avatar">${esc((p.owner_assigned||'T')[0])}</span>${esc(p.owner_assigned||'Unassigned')}<span>${esc(p.stage)}</span></div></button></article>`}).join('')||emptyState('No accounts match','Try another search or clear the filters.');};
function assetUrl(a){return safeUrl(a?.deployment_url||a?.url)}
function assetThumbnail(a,p){if(/wave 2/i.test(a?.title||''))return accountVisual(p);return safeUrl(a?.metadata?.thumbnail_url||a?.metadata?.preview_image||a?.metadata?.image_url)||accountProducts(p)||accountVisual(p)}
function assetPreview(a,p,live=false){const u=assetUrl(a),img=assetThumbnail(a,p),isImage=/\.(png|jpe?g|webp|gif|svg)(\?|$)/i.test(u)||/image|packaging/i.test(a?.asset_type||'')&&/\.(png|jpe?g|webp)/i.test(u);return `<div class="asset-preview ${live?'is-live':''}">${u&&isImage?`<img src="${esc(u)}" alt="${esc(a.title)}" loading="lazy">`:u&&live?`<iframe title="${esc(a.title||'Live asset preview')}" src="${esc(u)}" loading="lazy" sandbox="allow-scripts allow-same-origin allow-forms allow-popups"></iframe>`:img?`<img src="${esc(img)}" alt="${esc(p?.company||a?.title)} concept overview" loading="lazy"><div class="preview-overlay"><span>${icon('assets')}${esc(a?.asset_type||'Concept')}</span><b>${esc(a?.title||'Account concept')}</b>${u?`<button class="btn" onclick="loadAssetPreview(this,'${esc(u)}')">Load live preview</button>`:''}</div>`:`<div class="asset-preview-empty">${icon('assets')}<b>${esc(a?.title||'A vision starts here')}</b><span>${u?'Open the asset or load its live preview.':'Assign Ahamed a clear brief to begin.'}</span>${u?`<button class="btn" onclick="loadAssetPreview(this,'${esc(u)}')">Load live preview</button>`:''}</div>`}</div>`}
window.loadAssetPreview=(button,url)=>{if(!safeUrl(url))return;const box=button.closest('.asset-preview');box.innerHTML=`<iframe title="Live asset preview" src="${esc(url)}" sandbox="allow-scripts allow-same-origin allow-forms allow-popups"></iframe>`;box.classList.add('is-live')};
renderAssets=function(){const jobs=[...data.asset_work_requests].sort((a,b)=>new Date(b.updated_at)-new Date(a.updated_at)),active=jobs.filter(j=>['queued','in_progress','ready_for_review','changes_requested'].includes(j.status));$('#assetQueueCount').textContent=active.length+' active';$('#assetQueue').innerHTML=active.map(j=>{const p=data.prospects.find(p=>p.id===j.prospect_id),d=jobDeliverables(j.id).at(-1);return `<article class="asset-job-card ${j.status==='ready_for_review'?'amber':'cyan'}"><button class="card-open" onclick="openAssetJob('${j.id}')">${identityArt(p)}<div class="row"><span class="eyebrow">AHAMED</span><span class="status-chip ${j.status==='ready_for_review'?'amber':'cyan'}">${esc(j.status.replaceAll('_',' '))}</span></div><h3>${esc(j.title||'Asset build')}</h3><p>${esc(p?.company||'Account')} · ${esc(j.priority||'normal')}</p><div class="job-progress"><i style="width:${j.status==='queued'?18:j.status==='in_progress'?50:90}%"></i></div><span class="job-next">${j.status==='ready_for_review'?'Review submission':j.status==='changes_requested'?'Revision requested':'View brief & activity'}${icon('arrow')}</span></button></article>`}).join('')||emptyState('No active builds','Open an account and send its brief to Ahamed.');$('#assetLibraryCount').textContent=data.assets.length+' assets';$('#assetLibrary').innerHTML=data.assets.map(a=>{const p=data.prospects.find(p=>p.id===a.prospect_id),img=assetThumbnail(a,p);return `<article class="asset-card"><button class="asset-library-preview" onclick="openAsset('${a.id}')">${img?`<img src="${esc(img)}" alt="${esc(a.title)} concept overview" loading="lazy">`:icon('assets')}<span>${esc(a.asset_type||'Asset')}</span></button><div class="asset-card-body"><div class="row"><span class="eyebrow">${esc(p?.company||'Account')}</span><span class="status-chip ${statusClass(a.status)}">${esc(a.status||'Saved')}</span></div><h3>${esc(a.title)}</h3><div class="asset-actions"><button class="btn" onclick="openAsset('${a.id}')">Preview</button>${assetUrl(a)?`<a class="text-link" href="${esc(assetUrl(a))}" target="_blank" rel="noopener">Open live ${icon('external')}</a>`:''}</div></div></article>`}).join('')||emptyState('The studio is ready','Assets will appear here when saved or returned by Ahamed.');};
window.openAsset=id=>{const a=data.assets.find(x=>x.id===id);if(!a)return;const p=data.prospects.find(p=>p.id===a.prospect_id),vs=data.asset_versions.filter(v=>v.asset_id===id);modal(a.title,`<div class="review-summary">${identityArt(p)}<div><b>${esc(p?.company||'Account')}</b><span>${esc(a.asset_type||'Asset')} · ${esc(a.status||'Saved')}</span></div>${assetUrl(a)?`<a class="btn" href="${esc(assetUrl(a))}" target="_blank" rel="noopener">Open live ${icon('external')}</a>`:''}</div>${assetPreview(a,p)}<div class="asset-thumbs">${vs.map(v=>`<a class="asset-thumb" href="${esc(safeUrl(v.deployment_url||v.url))}" target="_blank" rel="noopener"><b>${esc(v.version_label||'Version')}</b><span>${esc(v.status||'Saved')}</span></a>`).join('')}</div><div class="brief-text">${esc(a.notes||'')}</div><button class="btn" onclick="closeModal();route('#/prospect/${a.prospect_id}')">Open account</button>`);$('#modalCard').classList.add('review-modal');};
openAssetJob=function(id){const j=data.asset_work_requests.find(j=>j.id===id);if(!j)return;const p=data.prospects.find(p=>p.id===j.prospect_id),ds=jobDeliverables(id),last=ds.find(d=>d.is_primary)||ds.at(-1),a=last?{...last,url:last.deployment_url||last.url,asset_type:last.kind}:pAssets(j.prospect_id)[0];modal('Asset review',`<div class="review-summary"><span class="avatar">A</span><div><b>Ahamed · ${esc(p?.company||'Account')}</b><span>${esc(j.status.replaceAll('_',' '))} · ${esc(j.priority||'normal')}</span></div><span class="status-chip ${j.status==='ready_for_review'?'amber':'cyan'}">${esc(j.status.replaceAll('_',' '))}</span></div><h3>${esc(j.title)}</h3>${assetPreview(a,p)}<div class="asset-thumbs">${ds.map(d=>`<a class="asset-thumb" href="${esc(safeUrl(d.deployment_url||d.url))}" target="_blank" rel="noopener">${icon('assets')}<b>${esc(d.version_label||d.title||'Submission')}</b></a>`).join('')}</div><details class="review-brief"><summary>Build brief & history</summary><div class="brief-text">${esc(j.request_text||'')}</div>${jobNotes(id).map(n=>`<div class="note-card"><b>${esc(n.author_name||n.author_type)}</b><p>${esc(n.body)}</p><time>${timeAgo(n.created_at)}</time></div>`).join('')}</details>${j.status==='ready_for_review'?`<div class="field"><label for="jobReviewNote">Review note</label><textarea id="jobReviewNote" placeholder="What works? What needs to change?"></textarea></div><div class="editor-actions review-actions"><button class="btn lime" onclick="reviewAssetJob('${id}','approved')">${icon('check')}Approve asset</button><button class="btn" onclick="reviewAssetJob('${id}','changes_requested')">Request revision</button></div>`:''}`);$('#modalCard').classList.add('review-modal');};window.openAssetJob=openAssetJob;
const originalReviewAssetJob=reviewAssetJob;reviewAssetJob=async function(id,decision){if(decision==='changes_requested'&&!$('#jobReviewNote')?.value.trim())return toast('Add a clear revision note for Ahamed.');await originalReviewAssetJob(id,decision)};window.reviewAssetJob=reviewAssetJob;
let accountTab='brief';
window.setAccountTab=tab=>{accountTab=tab;renderProspectDetail(currentProspect.id)};
renderProspectDetail=function(id){const p=data.prospects.find(p=>p.id===id);if(!p)return route('#/prospects');if(currentProspect?.id!==id)accountTab='brief';currentProspect=p;const w=workflowFor(id),phase=w?.phase||'research',assets=pAssets(id),jobs=pJobs(id),reports=pResearch(id),researchNotes=pNotes(id).filter(n=>/^research/i.test(n.title||'')),draft=pDrafts(id).find(d=>d.status==='draft'),active=assets.find(a=>a.id===currentAssetId)||assets.find(a=>/future-state/i.test(a.title))||assets[0],sources=[...new Set([...(reports[0]?.source_urls||[]),p.website,...(Array.isArray(p.source_notes)?p.source_notes:[])].filter(safeUrl))];currentAssetId=active?.id||null;
 const insight=reports[0]?.structured?.asset_recommendation?.concept||reports[0]?.structured?.fit||w?.reason||p.next_action||'Research the account to uncover its strongest commercial opportunity.';
 const brief=`<section class="panel detail-card account-brief"><div class="panel-head"><h2>Opportunity brief</h2><button class="text-link" onclick="openEditProspect('${id}')">Edit account</button></div>${briefFor(p).map(x=>`<div class="brief-stat">${icon('check')}<div><b>${esc(x[1])}</b><small>${esc(x[2])}</small></div></div>`).join('')}<div class="brief-text">${esc(reports[0]?.summary||researchNotes[0]?.body||p.notes||'Research this account to build a sourced opportunity brief.')}</div><div class="contact-block"><span class="eyebrow">CONTACT</span><b>${esc(p.contact_name||'Contact not yet verified')}</b>${p.contact_email?`<a href="mailto:${esc(p.contact_email)}">${esc(p.contact_email)}</a>`:'<span>No email saved</span>'}<span>${esc(p.contact_role||'')}</span><button class="text-link" onclick="openEditProspect('${id}')">Update contact</button></div></section>`;
 const research=`<section class="panel detail-card account-research"><div class="panel-head"><h2>Research dossier</h2><button class="btn" onclick="startResearch('${id}')">${icon('research')} ${reports.length?'Refresh research':'Start research'}</button></div>${researchNotes.map(n=>`<article class="research-report"><span class="eyebrow">Saved research · ${esc(n.created_by||'Team')}</span><div class="brief-text">${esc(n.body)}</div><div class="source-list">${(String(n.body).match(/https?:\/\/[^\s]+/g)||[]).filter(safeUrl).map(u=>`<a href="${esc(u)}" target="_blank" rel="noopener">${esc(new URL(u).hostname)}${icon('external')}</a>`).join('')}</div></article>`).join('')}${reports.map(r=>`<article class="research-report"><span class="eyebrow">${esc(timeAgo(r.created_at))} · ${esc(r.provider||'Research')}</span><div class="brief-text">${esc(r.summary)}</div>${r.structured?.fit?`<div class="insight-block"><b>Commercial fit</b><p>${esc(r.structured.fit)}</p></div>`:''}<div class="source-list">${(r.source_urls||[]).filter(safeUrl).map(u=>`<a target="_blank" rel="noopener" href="${esc(u)}">${esc(new URL(u).hostname)}${icon('external')}</a>`).join('')}</div></article>`).join('')||(!researchNotes.length?emptyState('What do we need to know?','Start research to save verified sources and account insights.'):'')}<div class="source-list">${sources.map(u=>`<a href="${esc(u)}" target="_blank" rel="noopener">${esc(new URL(u).hostname.replace(/^www\./,''))}${icon('external')}</a>`).join('')}</div></section>`;
 const studio=`<section class="panel detail-card account-studio"><div class="panel-head"><h2>Asset studio</h2><span class="status-chip ${phaseTone(phase)}">${jobs.some(j=>j.status==='ready_for_review')?'Awaiting review':active?esc(active.status||'Saved'):'No asset'}</span></div>${assetPreview(active,p)}<div class="asset-thumbs">${assets.map(a=>`<button class="asset-thumb ${a.id===currentAssetId?'active':''}" onclick="selectAsset('${a.id}')" aria-label="${esc(a.title)}">${assetThumbnail(a,p)?`<img src="${esc(assetThumbnail(a,p))}" alt="" loading="lazy">`:icon('assets')}<b>${esc(a.title)}</b><span>${esc(a.asset_type)}</span></button>`).join('')}</div>${ahamedStrip(p,jobs)}<div class="editor-actions">${active&&assetUrl(active)?`<a class="btn" target="_blank" rel="noopener" href="${esc(assetUrl(active))}">Open live concept ${icon('external')}</a>`:''}<button class="btn" onclick="assignAhamed('${id}')">${jobs.length?'New asset brief':'Send to Ahamed'}</button></div></section>`;
 const activities=`<section class="panel detail-card account-timeline"><div class="panel-head"><h2>Account timeline</h2><button class="text-link" onclick="addProspectNote('${id}')">Add note</button></div>${[...pActivities(id).map(a=>({title:a.activity_type||'Activity',body:a.subject||a.outcome||'',by:a.actor_name,at:a.occurred_at})),...pNotes(id).map(n=>({title:n.title,body:n.body,by:n.created_by,at:n.created_at||n.updated_at})),...data.reminders.filter(r=>r.prospect_id===id).map(r=>({title:r.title,body:'Due '+new Date(r.due_at).toLocaleString(),by:r.owner_assigned,at:r.created_at,status:r.status,id:r.id}))].sort((a,b)=>new Date(b.at)-new Date(a.at)).map(n=>`<article class="timeline-event"><i>${icon(n.id?'clock':'note')}</i><div><b>${esc(n.title)}</b><p>${esc(n.body)}</p><span>${esc(n.by||'Team')} · ${esc(timeAgo(n.at))}${n.status?' · '+esc(n.status):''}</span>${n.id&&n.status==='open'?`<button class="text-link" onclick="completeReminder('${n.id}')">Complete reminder</button>`:''}</div></article>`).join('')||emptyState('A fresh case file','Notes, reminders and activity stay attached to this account.')}</section>`;
 $('#prospectDetail').innerHTML=`<div class="account-breadcrumb"><button class="text-link" onclick="route('#/prospects')">Prospects</button><span>/</span>${esc(p.category||'Account')}</div><div class="prospect-top"><button class="icon-btn back-account" aria-label="Back to prospects" onclick="route('#/prospects')">${icon('arrow')}</button>${identityArt(p)}<div class="account-title"><div class="eyebrow">${esc(p.category||'Account')} · ${esc(p.owner_assigned||'Unassigned')}</div><h1>${esc(p.company)}</h1><p><span class="status-chip ${phaseTone(phase)}">${humanPhase(phase)}</span> ${esc(p.segment||p.location||'Opportunity account')}</p></div><button class="btn lime next-primary" onclick="runProspectNextMove('${id}')">${icon(phaseIcon(phase))}${esc(w?.recommended_action||'Research account')}</button></div><div class="step-rail">${['Research','Assets','Review','Outreach'].map((label,i)=>stepHtml(label,i+1,i===0?researchExists(p):i===1?assets.length>0:i===2?jobs.some(j=>j.status==='approved'):pMessages(id).some(m=>m.direction==='outbound'),i===0?phase==='research':i===1?phase==='asset_build':i===2?phase==='asset_review':/draft|reply|follow|waiting/.test(phase))).join('')}</div><div class="account-tabs" role="tablist">${[['brief','Brief'],['research','Research'],['assets','Assets'],['activity','Activity']].map(([k,l])=>`<button role="tab" aria-selected="${accountTab===k}" class="${accountTab===k?'active':''}" onclick="setAccountTab('${k}')">${l}</button>`).join('')}</div><div class="prospect-layout tab-${accountTab}"><div class="account-col brief-col">${brief}${research}</div><div class="account-col studio-col">${studio}${activities}</div><aside class="detail-right"><section class="copilot-insight"><div class="eyebrow">${icon('ai')} MORPHEUS INSIGHT</div><h3>${esc(w?.recommended_action||'Define the next move')}</h3><p>${esc(String(insight))}</p><button class="text-link" onclick="openCopilot('${id}','What should happen next for this account?')">Ask about this account ${icon('arrow')}</button></section><section class="panel detail-card outreach-draft-card"><div class="panel-head"><h2>Outreach</h2><span class="status-chip ${draft?.status==='sent'?'cyan':'lime'}">${esc(draft?.status||'No draft')}</span></div><textarea id="prospectDraftBody" aria-label="Account outreach draft" placeholder="Prepare a draft from account context…">${esc(draft?.body||'')}</textarea><div class="editor-actions"><button class="btn lime" onclick="aiWrite('${id}')">${icon('ai')} Prepare outreach</button><button class="btn" onclick="saveProspectDraft('${id}')">Save draft</button></div></section><section class="panel detail-card next-action-card"><div class="eyebrow">NEXT MOVE</div><h3>${esc(w?.recommended_action||p.next_action||'Define the next move')}</h3><p>${esc(w?.reason||'')}</p><div class="move-meta"><span class="micro-avatar">${esc((p.owner_assigned||'T')[0])}</span>${esc(p.owner_assigned||'Unassigned')}</div><div class="editor-actions"><button class="btn lime account-mobile-primary" onclick="runProspectNextMove('${id}')">${icon(phaseIcon(phase))}${esc(w?.recommended_action||'Next move')}</button><button class="btn" onclick="addProspectNote('${id}')">${icon('note')} Add note</button><button class="btn" onclick="addProspectReminder('${id}')">${icon('clock')} Reminder</button></div></section></aside></div>`;
};
window.completeReminder=async id=>{await rpc('sales_os_save_reminder',{p_token:token||null,p_payload:{id,status:'completed'}});await load();toast('Reminder completed')};
renderDraftEditor=function(d){const p=data.prospects.find(p=>p.id===d.prospect_id),w=workflowFor(d.prospect_id),conn=data.gmail_connections.find(c=>c.active&&c.member_email===actor?.email);$('#draftEditor').innerHTML=`<div class="writer-head"><div><div class="eyebrow">OUTREACH WORKSPACE</div><h2>${esc(p?.company||'Email draft')}</h2></div><span class="status-chip ${d.status==='sent'?'cyan':'lime'}">${esc(d.status)}</span></div><div class="writer-layout"><div class="writing-surface"><div class="mail-field"><label for="draftTo">To</label><input id="draftTo" class="control" type="email" value="${esc(d.recipient||'')}" ${d.status==='sent'?'readonly':''}></div><div class="mail-field subject-field"><label for="draftSubject">Subject</label><input id="draftSubject" class="control" value="${esc(d.subject||'')}" ${d.status==='sent'?'readonly':''}></div><textarea id="draftBody" aria-label="Email message" ${d.status==='sent'?'readonly':''}>${esc(d.body||'')}</textarea>${d.status!=='sent'?`<div class="refine-toolbar"><span>${icon('ai')} Refine with Morpheus</span><button onclick="refineCurrentDraft('Make this more concise without changing facts')">Shorter</button><button onclick="refineCurrentDraft('Make this warmer and more personal')">Warmer</button><button onclick="refineCurrentDraft('Strengthen the opening and one clear call to action')">Stronger opening</button></div><div class="editor-actions writer-actions"><button class="btn" onclick="saveDraft()">Save draft</button><button class="btn lime" onclick="sendDraft()">Review & send ${icon('mail')}</button></div>`:''}</div><aside class="writer-context"><div class="eyebrow">ACCOUNT CONTEXT</div>${identityArt(p)}<h3>${esc(p?.company||'Account')}</h3><span class="status-chip ${phaseTone(w?.phase||'research')}">${humanPhase(w?.phase)}</span><p>${esc(pResearch(d.prospect_id)[0]?.summary||p?.notes||'No research saved yet.')}</p><div class="context-stat"><b>${pAssets(d.prospect_id).length}</b><span>saved assets</span></div><div class="mailbox-state ${conn?'cyan':''}">${icon('mail')}<div><b>${conn?'Gmail connected':'Gmail not connected'}</b><small>${esc(conn?.google_email||'Connect in Settings')}</small></div></div><button class="text-link" onclick="route('#/prospect/${d.prospect_id}')">Open account ${icon('arrow')}</button></aside></div>`;};
window.refineCurrentDraft=instruction=>{if(!currentDraft)return;openCopilot(currentDraft.prospect_id,`${instruction}. Return a subject and body. Keep all verified facts.\n\nCURRENT SUBJECT: ${$('#draftSubject').value}\nCURRENT DRAFT:\n${$('#draftBody').value}`)};
const actualSendDraft=sendDraft;sendDraft=async function(){if(!currentDraft)return;if(!$('#draftTo').value.trim()||!$('#draftSubject').value.trim()||!$('#draftBody').value.trim())return toast('Add recipient, subject and message first.');await saveDraft();const d=currentDraft;modal('Review email before sending',`<div class="send-review"><span class="eyebrow">SEND VIA GMAIL</span><b>To: ${esc(d.recipient)}</b><h3>${esc(d.subject)}</h3><div class="brief-text">${esc(d.body)}</div><p class="quiet">This sends the email to the recipient above.</p><div class="editor-actions"><button id="confirmSendEmail" class="btn lime">Send email</button><button class="btn" onclick="closeModal()">Keep draft</button></div></div>`);$('#confirmSendEmail').onclick=async()=>{closeModal();await actualSendDraft()};};
renderPipeline=function(){const stages=STAGES,stalled=data.workflow_state.filter(w=>w.urgency>=90).length;$('#pipelineSignals').innerHTML=`<div class="signal cyan">${icon('pipeline')}<strong>${data.prospects.filter(p=>!['Won','Lost','Disqualified'].includes(p.stage)).length}</strong><span>Open accounts</span></div><div class="signal amber">${icon('clock')}<strong>${stalled}</strong><span>Need attention</span></div><div class="signal lime">${icon('check')}<strong>${data.prospects.filter(p=>['Qualified','Meeting','Proposal','Negotiation'].includes(p.stage)).length}</strong><span>Commercial accounts</span></div>`;$('#pipelineBoard').innerHTML=stages.map(stage=>{const ps=data.prospects.filter(p=>p.stage===stage);return `<section class="pipeline-lane ${statusClass(stage)}"><div class="pipeline-lane-head"><span>${stage}</span><b>${ps.length}</b></div>${ps.slice(0,50).map(p=>`<button class="pipeline-deal" onclick="route('#/prospect/${p.id}')">${identityArt(p)}<div><b>${esc(p.company)}</b><span>${esc(workflowFor(p.id)?.recommended_action||p.next_action||p.category||'')}</span><small>${esc(p.owner_assigned||'Unassigned')}</small></div></button>`).join('')||'<div class="lane-empty">No accounts at this stage</div>'}</section>`}).join('');};
function contextPrompt(request,id=null){const p=data.prospects.find(p=>p.id===id);const context=p?{company:p.company,category:p.category,website:p.website,stage:p.stage,assignee:p.owner_assigned,contact:p.contact_name,contact_email:p.contact_email,next_move:workflowFor(id),research:pResearch(id).slice(0,2),research_notes:pNotes(id).filter(n=>/^research/i.test(n.title||'')).slice(0,2).map(n=>({title:n.title,body:n.body})),assets:pAssets(id).map(a=>({title:a.title,status:a.status,url:assetUrl(a)})),asset_jobs:pJobs(id).map(j=>({title:j.title,status:j.status,brief:j.request_text})),drafts:pDrafts(id).slice(0,2).map(d=>({subject:d.subject,body:d.body,status:d.status}))}:{ranked_actions:todayQueue.slice(0,12),priority_accounts:priorityProspects().map(p=>({company:p.company,stage:p.stage,next_move:workflowFor(p.id)?.recommended_action}))};return 'You are Morpheus, our sales intelligence partner. Use only the verified Sales OS context below. Do not invent facts. Present a reviewable plan before any action. Do not send emails without confirmation.\n\nREQUEST:\n'+request+'\n\nSALES OS CONTEXT:\n'+JSON.stringify(context,null,2)}
function discoveryPrompt(){return `Find ${$('#fpCount')?.value||20} real B2B prospects for ${$('#fpCategory')?.value||'our target market'} in ${$('#fpGeo')?.value||'the target geography'}. ${$('#fpCriteria')?.value||''} Use current public sources and verify contacts. Do not invent facts. Return company, category, website, contact_name, contact_email, location, why_fit and source URLs in a CSV for Morpheus Sales OS.`}
function openContextChat(prompt){const url='https://chatgpt.com/?q='+encodeURIComponent(prompt);if(url.length<24000){window.open(url,'_blank','noopener');toast('Opened ChatGPT with your prompt and context.')}else{modal('Continue in ChatGPT',`<p class="brief-text">This account has a large context. Copy the full prompt, then open ChatGPT.</p><textarea id="fullChatPrompt" readonly aria-label="Full ChatGPT prompt">${esc(prompt)}</textarea><div class="editor-actions"><button id="copyFullPrompt" class="btn lime">Copy full prompt</button><a class="btn" href="https://chatgpt.com/?q=${encodeURIComponent('Continue the Morpheus Sales OS request using the full account context I will paste next.')}" target="_blank" rel="noopener">Open prepared chat</a></div>`);$('#copyFullPrompt').onclick=()=>navigator.clipboard.writeText(prompt).then(()=>toast('Full context copied'));}}
aiWrite=function(id){const p=data.prospects.find(p=>p.id===id);if(!p)return;const prompt=contextPrompt('Write the best concise next sales email using the latest research and approved assets. Return SUBJECT and BODY.',id);if(providerStatus.ai)openCopilot(id,'Draft the best concise next sales email using latest research and approved assets. Return subject and body.');else openContextChat(prompt)};window.aiWrite=aiWrite;
const originalStartResearch=startResearch;startResearch=async function(id){const p=data.prospects.find(p=>p.id===id);if(!p)return;if(!providerStatus.ai){openContextChat(contextPrompt(researchPrompt(p),id));return captureResearch(id)};await originalStartResearch(id)};window.startResearch=startResearch;
const originalSendCopilot=sendCopilot;sendCopilot=async function(){if(!providerStatus.ai){const msg=$('#copilotInput').value.trim();if(msg)openContextChat(contextPrompt(msg,copilotProspectId));return}await originalSendCopilot()};
const originalRunUniversalCommand=runUniversalCommand;runUniversalCommand=async function(command){if(!providerStatus.ai){lastCommandPlan=workspacePlan(command);renderCommandPlan(command);return}await originalRunUniversalCommand(command);$('#universalCommandRun').innerHTML=icon('arrow')};
renderCopilotMsgs=function(){$('#copilotMessages').innerHTML=copilotLocal.map((m,i)=>`<div class="copilot-msg ${m.role}"><div class="message-label">${m.role==='assistant'?'MORPHEUS':'YOU'}</div><div>${esc(m.content)}</div>${m.role==='assistant'&&(m.structured?.draft?.body||m.structured?.body)?`<button class="btn lime" onclick="saveCopilotDraft(${i})">Save as draft</button>`:''}</div>`).join('');$('#copilotMessages').scrollTop=$('#copilotMessages').scrollHeight};
window.saveCopilotDraft=async i=>{const m=copilotLocal[i],p=data.prospects.find(p=>p.id===copilotProspectId);const draft=m?.structured?.draft||m?.structured;if(!draft?.body||!p)return toast('Choose an account first.');await rpc('sales_os_save_email_draft',{p_token:token||null,p_payload:{prospect_id:p.id,recipient:p.contact_email||'',sender_name:actor?.display_name||'',sender_email:actor?.email||'',subject:draft.subject||'',body:draft.body,status:'draft',ai_assisted:true,provider:'morpheus_copilot',created_by:actor?.display_name||'Sales OS'}});await load();toast('AI draft saved')};
renderCommandPlan=function(command=''){const plan=lastCommandPlan||{answer:'',actions:[]};modal('Morpheus action plan',`<div class="plan-intro">${icon('ai')}<div><span class="eyebrow">REVIEW BEFORE RUNNING</span><p>${esc(plan.answer||'Here is the next move.')}</p></div></div><div class="command-plan-list">${(plan.actions||[]).map((a,i)=>`<article class="command-plan-card ${a._done?'done':''}"><div class="plan-number">${a._done?icon('check'):String(i+1).padStart(2,'0')}</div><div class="plan-content"><b>${esc(a.label||a.type)}</b><p>${esc(a.reason||'')}</p>${a.prospect_id?`<span class="quiet">${esc(prospectName(a.prospect_id))}</span>`:''}<div class="plan-payload">${Object.entries(a.payload||{}).filter(([k,v])=>typeof v==='string'&&v).map(([k,v])=>`<details><summary>${esc(k.replaceAll('_',' '))}</summary><p>${esc(v)}</p></details>`).join('')}</div><div class="actions"><button class="btn ${a.requires_confirmation?'lime':''}" ${a._done?'disabled':''} onclick="runCommandAction(${i})">${a._done?'Completed':a.requires_confirmation?'Confirm & run':'Run action'}</button>${a.prospect_id?`<button class="text-link" onclick="closeModal();route('#/prospect/${a.prospect_id}')">Open account</button>`:''}</div></div><span class="workflow-pill">${a.requires_confirmation?'Confirmation required':a._done?'Done':'Ready'}</span></article>`).join('')||emptyState('No action required','Ask a follow-up to explore the next move.')}</div>`);};
const originalRoute=route;route=function(hash,push=true){originalRoute(hash,push);const labels={command:'Command centre',prospects:'Prospects',prospect:'Account control room',research:'Research intelligence',assets:'Asset studio',outreach:'Outreach workspace',pipeline:'Commercial pipeline',settings:'Connections',ai:'Ask Morpheus'};$('#routeLabel').textContent=labels[currentRoute]||'Sales OS';if(currentRoute==='prospect')$$('[data-route="prospects"]').forEach(b=>b.classList.add('active'));};
const originalModal=modal;let modalReturnFocus=null;modal=function(title,body){modalReturnFocus=document.activeElement;$('#modalCard').classList.remove('review-modal');originalModal(title,body);$('#modalCard').setAttribute('aria-label',title);decorateControls($('#modalCard'));setTimeout(()=>$('#modalCard').querySelector('input,textarea,select,button')?.focus(),30)};
const originalCloseModal=closeModal;closeModal=function(){originalCloseModal();modalReturnFocus?.focus?.()};
function decorateControls(root=document){root.querySelectorAll('.field label').forEach(label=>{const input=label.parentElement.querySelector('input,select,textarea');if(input?.id)label.htmlFor=input.id});root.querySelectorAll('.icon-btn').forEach(b=>{if(b.textContent.trim()==='×'){b.innerHTML=icon('close');b.setAttribute('aria-label','Close')}})}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();closeCopilot();closeSheet()}if(e.key==='Tab'){const overlay=!$('#modal').classList.contains('hidden')?$('#modalCard'):!$('#copilot').classList.contains('hidden')?$('.copilot-panel'):!$('#moreSheet').classList.contains('hidden')?$('.sheet-panel'):null;if(overlay){const f=[...overlay.querySelectorAll('button,a,input,select,textarea')].filter(x=>!x.disabled&&!x.hidden&&x.offsetParent!==null);if(!f.length)return;if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus()}}}});
window.addEventListener('unhandledrejection',event=>{toast('Could not finish: '+String(event.reason?.message||event.reason));});
