const originalNextMove=window.runProspectNextMove;window.runProspectNextMove=id=>{const phase=workflowFor(id)?.phase;if(phase==='follow_up'||phase==='contacted'){aiWrite(id);return}if(phase==='asset_build'){const job=pJobs(id).find(j=>['queued','in_progress','changes_requested'].includes(j.status));if(job)return openAssetJob(job.id)}originalNextMove(id)};
openEditProspect=function(id){const p=data.prospects.find(p=>p.id===id);if(!p)return;modal('Edit account',`<div class="field"><label for="epCompany">Company</label><input id="epCompany" class="control" value="${esc(p.company)}"></div><div class="field"><label for="epContact">Contact</label><input id="epContact" class="control" value="${esc(p.contact_name||'')}"></div><div class="field"><label for="epEmail">Email</label><input id="epEmail" class="control" type="email" value="${esc(p.contact_email||'')}"></div><div class="field"><label for="epWebsite">Website</label><input id="epWebsite" class="control" type="url" value="${esc(p.website||'')}"></div><div class="field"><label for="epAssignee">Assigned to</label><select id="epAssignee" class="control"><option ${p.owner_assigned==='Saad'?'selected':''}>Saad</option><option ${p.owner_assigned==='Yazeed'?'selected':''}>Yazeed</option><option value="" ${!p.owner_assigned?'selected':''}>Unassigned</option></select></div><div class="field"><label for="epStage">Commercial stage</label><select id="epStage" class="control">${STAGES.map(s=>`<option ${p.stage===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label for="epNext">Next action</label><input id="epNext" class="control" value="${esc(p.next_action||'')}"></div><button id="saveProspectEdit" class="btn lime wide">Save changes</button>`);$('#saveProspectEdit').onclick=async()=>{if(!$('#epCompany').value.trim())return toast('Company is required');await rpc('sales_os_save_prospect',{p_token:token||null,p_payload:{id,company:$('#epCompany').value.trim(),contact_name:$('#epContact').value,contact_email:$('#epEmail').value,website:$('#epWebsite').value,owner_assigned:$('#epAssignee').value,stage:$('#epStage').value,next_action:$('#epNext').value}});closeModal();await load();renderProspectDetail(id);toast('Account updated')}};window.openEditProspect=openEditProspect;
connectGmail=async function(){const popup=window.open('about:blank','morpheus-gmail','width=620,height=740');if(!popup)return toast('Allow the Gmail connection window to open.');try{const r=await fetch(SUPABASE_URL+'/functions/v1/sales-os-gmail-oauth',{method:'POST',headers:{'Content-Type':'application/json',apikey:APIKEY,Authorization:'Bearer '+sessionAccessToken},body:'{}'});const d=await r.json();if(!r.ok||!safeUrl(d.authorization_url))throw new Error(d.error||'Could not connect Gmail');popup.location.href=d.authorization_url;const started=Date.now(),poll=setInterval(async()=>{if(popup.closed||Date.now()-started>600000){clearInterval(poll);return}try{if(popup.location.origin===location.origin&&popup.location.search.includes('gmail=')){const q=new URLSearchParams(popup.location.search),result=q.get('gmail');popup.close();clearInterval(poll);closeModal();await load();toast(result==='connected'?'Gmail connected':q.get('detail')||'Gmail connection could not finish')}}catch{}},1000)}catch(e){popup.close();toast(String(e.message||e))}};
window.showAllToday=()=>modal('Adaptive Today',`<div class="all-today">${todayQueue.map((x,i)=>`<article class="move-card ${phaseTone(x.action_kind)}">${identityArt(data.prospects.find(p=>p.id===x.prospect_id))}<div class="move-content"><div class="move-kicker">${esc(x.action_label)} · ${esc(x.assigned_to||'Team')}</div><h3>${esc(x.title)}</h3><p>${esc(x.reason)}</p></div><button class="btn" onclick="closeModal();runTodayItem(${i})">${esc(x.action_label||'Open')}</button></article>`).join('')}</div>`);
$('.priority-panel .text-link').onclick=window.showAllToday;
