window.startVoiceCommand=(targetId='universalCommandInput')=>{const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){$('#'+targetId).focus();return toast('Voice input is unavailable in this browser. Type your request.')}const recognition=new Speech();recognition.lang='en-US';recognition.interimResults=false;recognition.onresult=e=>{$('#'+targetId).value=e.results[0][0].transcript;toast('Voice captured. Review your request and run it.')};recognition.onerror=e=>toast(e.error==='not-allowed'?'Microphone permission was not granted.':'Voice input could not finish.');recognition.start()};
