const loadOriginal=load;load=async function(){const busy=document.createElement('div');busy.className='workspace-loading';busy.setAttribute('role','status');busy.innerHTML=icon('ai')+'<span>Reading the latest workspace signals…</span>';$('#app').append(busy);try{await loadOriginal()}catch(e){if(!data.prospects.length){$('#app').classList.add('hidden');$('#login').classList.remove('hidden');$('#loginError').textContent='Could not load the workspace. Please try again.'}throw e}finally{busy.remove()}};
const accountRenderOriginal=renderProspectDetail;renderProspectDetail=function(id){const changed=currentProspect?.id!==id;if(changed)accountTab=matchMedia('(max-width:600px)').matches&&pAssets(id).length?'assets':'brief';accountRenderOriginal(id);if(changed&&matchMedia('(max-width:600px)').matches&&pAssets(id).length){accountTab='assets';accountRenderOriginal(id)}};

