saveProspectDraft=async function(id){const p=data.prospects.find(x=>x.id===id),body=$('#prospectDraftBody').value.trim();if(!body)return toast('Draft is empty');const existing=pDrafts(id).find(d=>d.status==='draft');await rpc('sales_os_save_email_draft',{p_token:token||null,p_payload:{id:existing?.id,prospect_id:id,recipient:p.contact_email||'',sender_name:actor?.display_name||'',sender_email:actor?.email||'',subject:existing?.subject||('A thought for '+p.company),body,status:'draft',ai_assisted:existing?.ai_assisted||false,provider:'sales_os',created_by:actor?.display_name||'Sales OS'}});await load();renderProspectDetail(id);toast('Draft saved')};window.saveProspectDraft=saveProspectDraft;
function workspacePlan(command){const q=String(command).trim(),normalized=q.toLowerCase().replace(/[’']/g,''),p=[...data.prospects].sort((a,b)=>b.company.length-a.company.length).find(p=>normalized.includes(p.company.toLowerCase().replace(/[’']/g,'')))||(/daves/i.test(q)?data.prospects.find(p=>/dave.*rare/i.test(p.company)):null)||(/remind|note/i.test(q)&&currentRoute==='prospect'?currentProspect:null),actions=[];const action=(type,label,reason,confirm=false,payload={})=>actions.push({type,label,reason,requires_confirmation:confirm,prospect_id:p?.id,payload});
 if(p&&/ahamed/i.test(q)){action('assign_ahamed','Send '+p.company+' to Ahamed','Review a scoped build brief before assigning this asset job.',true,{title:'Build prospect asset for '+p.company,request_text:researchPrompt(p)+'\nUse the latest saved research and approved account direction. Return a mobile-ready preview, live deployment and source repository.',priority:'normal'})}
 else if(p&&/remind/i.test(q)){action('create_reminder','Set reminder for '+p.company,'Choose and confirm the due date and assignee.',true)}
 else if(p&&/research/i.test(q)){action('research_prospect','Research '+p.company,'Open a prepared ChatGPT request with the saved account context and source requirements.')}
 else if(p&&/outreach|draft|email/i.test(q)){action('ai_write','Prepare outreach for '+p.company,'Use latest research, saved assets and workflow context. Open a prepared ChatGPT chat; review and save the resulting draft in Sales OS.')}
 else if(p){action('open_prospect','Open '+p.company,'Review research, assets and the next move in the account control room.')}
 else if(/find.*prospect/i.test(q)){action('find_prospects','Find new prospects','Choose the target market, geography and count before research.')}
 else if(/today|attention|prioriti|follow.?up/i.test(q)){todayQueue.filter(x=>!/follow/i.test(q)||/follow/i.test(x.action_label)).slice(0,3).forEach(x=>actions.push({type:'open_prospect',label:x.action_label+' · '+x.title,reason:x.reason,requires_confirmation:false,prospect_id:x.prospect_id,payload:{}}))}
 else action('continue_chat','Explore this with Morpheus','Open ChatGPT with your request and live workspace context.',false,{request:q});
 return {answer:p?'A reviewable next move for '+p.company+'.':'A plan from your live workspace evidence.',actions};}
const commandActionOriginal=window.runCommandAction;window.runCommandAction=async i=>{const a=lastCommandPlan?.actions?.[i];if(a?.type==='continue_chat'){openContextChat(contextPrompt(a.payload.request));a._done=true;renderCommandPlan();return}if(a?.type==='assign_ahamed'&&!providerStatus.ai){closeModal();assignAhamed(a.prospect_id);$('#ajTitle').value=a.payload.title;$('#ajRequest').value=a.payload.request_text;return}await commandActionOriginal(i)};

window.captureResearch=id=>{const p=data.prospects.find(p=>p.id===id);modal('Save research findings',`<p class="brief-text">A prepared research chat has opened. Save verified findings and source links here to move this account forward.</p><div class="field"><label for="researchSummary">Research findings</label><textarea id="researchSummary" placeholder="Paste verified findings, fit and the strongest next move…"></textarea></div><div class="field"><label for="researchSources">Source links</label><textarea id="researchSources" placeholder="One verified https:// source per line"></textarea></div><div class="editor-actions"><button id="saveResearchFindings" class="btn lime">Save research</button><button id="reopenResearchChat" class="btn">Open prepared chat</button></div>`);$('#reopenResearchChat').onclick=()=>openContextChat(contextPrompt(researchPrompt(p),id));$('#saveResearchFindings').onclick=async()=>{const summary=$('#researchSummary').value.trim(),sources=$('#researchSources').value.split(/\s+/).filter(Boolean);if(!summary)return toast('Add verified findings first');if(sources.some(u=>!safeUrl(u)))return toast('Use valid https:// source links');await rpc('sales_os_save_note',{p_token:token||null,p_payload:{prospect_id:id,title:'Research · '+p.company,body:summary+(sources.length?'\n\nSources:\n'+sources.join('\n'):''),pinned:true,created_by:actor?.display_name||'Sales OS'}});closeModal();await load();route('#/prospect/'+id);accountTab='research';renderProspectDetail(id);toast('Research saved')};};
